'use strict';

// Parse a compact duration like "1h30m", "45m", "90s" into seconds.
const UNIT_SECONDS = { h: 3600, m: 60, s: 1 };

function parseDuration(text) {
  const matches = [...String(text).trim().matchAll(/(\d+)([hms])/g)];
  if (!matches.length) throw new Error(`bad duration: ${text}`);
  return matches.reduce((total, m) => {
    const n = Number(m[1]);
    return total + n * UNIT_SECONDS[m[2]];
  }, 0);
}

module.exports = { parseDuration };

