const assert = require('node:assert');
const { parseDuration } = require('../src/duration');

test('parseDuration minutes', () => {
  assert.strictEqual(parseDuration('45m'), 2700);
});

test('parseDuration seconds', () => {
  assert.strictEqual(parseDuration('90s'), 90);
});

test('parseDuration rejects garbage', () => {
  assert.throws(() => parseDuration('soon'), /bad duration/);
  assert.throws(() => parseDuration('10x'), /bad duration/);
});

